import React, { useRef, useState } from 'react';
import rmsmLogo from '../assets/rmsm-logo.png';
import modiPhoto from '../assets/modi.jpg';
import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';

const API_BASE = 'http://localhost:5000';

function formatDate(dateStr) {
  if (!dateStr) return '';
  const d = new Date(dateStr);
  if (isNaN(d)) return dateStr;
  return d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
}

function getMembershipColor(type) {
  const colors = { Primary: '#FF6B00', Active: '#138808', Life: '#000080', Patron: '#C8A400' };
  return colors[type] || '#FF6B00';
}

// candidate: plain object with all fields
// photoPreview: base64 data URL from the upload (before submit), or null
export default function IDCard({ candidate, photoPreview }) {
  const cardRef = useRef(null);
  const [status, setStatus] = useState(''); // '', 'loading', 'done', 'error'
  const [statusMsg, setStatusMsg] = useState('');

  // Prefer the live preview base64 if available, else fallback to server URL
  const photoSrc = photoPreview
    ? photoPreview
    : candidate.photo_path
      ? `${API_BASE}${candidate.photo_path}`
      : null;

  const memberColor = getMembershipColor(candidate.membership_type);

  const captureCanvas = async (scale = 3) => {
    if (!cardRef.current) throw new Error('Card not found');
    return html2canvas(cardRef.current, {
      scale,
      useCORS: true,
      allowTaint: true,
      backgroundColor: '#ffffff',
      logging: false,
    });
  };

  const handleDownloadPDF = async () => {
    setStatus('loading');
    setStatusMsg('Generating PDF…');
    try {
      const canvas = await captureCanvas(3);
      const imgData = canvas.toDataURL('image/jpeg', 0.95);
      const pdf = new jsPDF({ orientation: 'landscape', unit: 'mm', format: [95, 60] });
      pdf.addImage(imgData, 'JPEG', 0, 0, 95, 60);
      pdf.save(`RMSM_Card_${candidate.candidate_id}.pdf`);
      setStatus('done');
      setStatusMsg('PDF downloaded!');
    } catch (err) {
      setStatus('error');
      setStatusMsg('PDF generation failed. Please try again.');
      console.error(err);
    }
  };

  const handleDownloadImage = async () => {
    setStatus('loading');
    setStatusMsg('Generating image…');
    try {
      const canvas = await captureCanvas(4);
      const link = document.createElement('a');
      link.download = `RMSM_Card_${candidate.candidate_id}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
      setStatus('done');
      setStatusMsg('Image downloaded!');
    } catch (err) {
      setStatus('error');
      setStatusMsg('Image generation failed. Please try again.');
      console.error(err);
    }
  };

  return (
    <div style={{ fontFamily: "'Poppins', 'Arial', sans-serif" }}>

      {/* ── Card Preview ─────────────────────────────────────── */}
      <div style={{ display: 'flex', justifyContent: 'center', marginBottom: 16 }}>
        <div
          ref={cardRef}
          style={{
            width: 380,
            borderRadius: 10,
            overflow: 'hidden',
            boxShadow: '0 6px 24px rgba(0,0,128,0.18)',
            background: '#fff',
            fontFamily: "'Poppins', 'Arial', sans-serif",
          }}
        >
          {/* Top tricolor stripe */}
          <div style={{
            height: 5,
            background: 'linear-gradient(to right, #FF6B00 33.33%, #ffffff 33.33%, #ffffff 66.66%, #138808 66.66%)',
          }} />

          {/* Header — Navy */}
          <div style={{
            background: 'linear-gradient(135deg, #000080 0%, #1a1a9e 100%)',
            padding: '8px 12px',
            display: 'flex',
            alignItems: 'center',
            gap: 10,
          }}>
            <img
              src={rmsmLogo}
              alt="RMSM"
              crossOrigin="anonymous"
              style={{ width: 42, height: 42, borderRadius: '50%', border: '2px solid #F0C429', objectFit: 'cover', flexShrink: 0 }}
            />
            <div style={{ flex: 1 }}>
              <div style={{ color: '#F0C429', fontSize: 13, fontWeight: 800, letterSpacing: '0.05em', lineHeight: 1.1 }}>RMSM</div>
              <div style={{ color: '#ffffff', fontSize: 8.5, opacity: 0.9, lineHeight: 1.3 }}>राष्ट्रीय मोदी सेवा मिशन</div>
              <div style={{ color: 'rgba(255,255,255,0.65)', fontSize: 7.5, lineHeight: 1.2 }}>सेवा | समर्पण | संस्कार</div>
            </div>
            <div style={{ textAlign: 'right' }}>
              <div style={{ color: 'rgba(255,255,255,0.55)', fontSize: 7, marginBottom: 2 }}>MEMBER ID</div>
              <div style={{ color: '#F0C429', fontSize: 9.5, fontWeight: 800, letterSpacing: '0.03em' }}>
                {candidate.candidate_id}
              </div>
              <div style={{
                display: 'inline-block',
                background: memberColor,
                color: '#fff',
                fontSize: 7,
                fontWeight: 700,
                padding: '2px 6px',
                borderRadius: 8,
                marginTop: 3,
                textTransform: 'uppercase',
                letterSpacing: '0.04em',
              }}>
                {candidate.membership_type}
              </div>
            </div>
          </div>

          {/* Body */}
          <div style={{ padding: '10px 12px', display: 'flex', gap: 10, background: 'linear-gradient(135deg, #fffaf5 0%, #ffffff 100%)' }}>

            {/* Photo column */}
            <div style={{ flexShrink: 0, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 5 }}>
              <div style={{ textAlign: 'center' }}>
                {photoSrc ? (
                  <img
                    src={photoSrc}
                    alt={candidate.full_name}
                    crossOrigin="anonymous"
                    style={{ width: 68, height: 82, borderRadius: 6, border: '2.5px solid #FF6B00', objectFit: 'cover', display: 'block' }}
                    onError={e => {
                      e.target.src = `https://ui-avatars.com/api/?name=${encodeURIComponent(candidate.full_name)}&background=FF6B00&color=fff&size=80`;
                    }}
                  />
                ) : (
                  <div style={{
                    width: 68, height: 82, borderRadius: 6, border: '2.5px solid #FF6B00',
                    background: '#FF6B00', display: 'flex', alignItems: 'center', justifyContent: 'center',
                    fontSize: 28, color: '#fff', fontWeight: 700,
                  }}>
                    {candidate.full_name ? candidate.full_name[0].toUpperCase() : '?'}
                  </div>
                )}
                <div style={{ fontSize: 7, color: '#9ca3af', marginTop: 2 }}>सदस्य फोटो</div>
              </div>

              {/* Modi photo */}
              <div style={{ textAlign: 'center' }}>
                <img
                  src={modiPhoto}
                  alt="PM Narendra Modi"
                  crossOrigin="anonymous"
                  style={{ width: 48, height: 55, borderRadius: 6, border: '2px solid #C8A400', objectFit: 'cover', objectPosition: 'center top', display: 'block' }}
                />
                <div style={{ fontSize: 6.5, color: '#6b7280', marginTop: 2, lineHeight: 1.2, textAlign: 'center' }}>
                  PM Narendra<br />Modi Ji
                </div>
              </div>
            </div>

            {/* Info column */}
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: 14, fontWeight: 800, color: '#000080', lineHeight: 1.15, marginBottom: 4 }}>
                {candidate.full_name}
              </div>
              <div style={{
                display: 'inline-block',
                background: '#FF6B00', color: '#fff',
                fontSize: 8, fontWeight: 700,
                padding: '2px 8px', borderRadius: 10, marginBottom: 7,
                textTransform: 'uppercase', letterSpacing: '0.04em',
              }}>
                {candidate.designation}
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 2.5 }}>
                <InfoRow label="पिता/Father" value={candidate.father_name} />
                <InfoRow label="जन्म/DOB" value={formatDate(candidate.dob)} />
                <InfoRow label="मोबाइल" value={candidate.mobile} />
                <InfoRow label="जिला/District" value={`${candidate.city}, ${candidate.district}`} />
                <InfoRow label="सदस्यता" value={`${candidate.membership_type} Member`} />
              </div>
            </div>
          </div>

          {/* Footer */}
          <div style={{
            background: 'linear-gradient(135deg, #FF6B00 0%, #D45500 100%)',
            padding: '6px 12px',
            display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          }}>
            <div>
              <div style={{ color: '#fff', fontSize: 8, opacity: 0.8 }}>सदस्यता तिथि</div>
              <div style={{ color: '#fff', fontSize: 9.5, fontWeight: 700 }}>{formatDate(candidate.joining_date)}</div>
            </div>
            <div style={{ textAlign: 'center' }}>
              <div style={{ color: '#fff', fontSize: 9, fontWeight: 700, letterSpacing: '0.03em' }}>संगठन संपूर्ण भारत</div>
              <div style={{ color: 'rgba(255,255,255,0.75)', fontSize: 7.5 }}>www.rmsm.org.in</div>
            </div>
            <div style={{ textAlign: 'right' }}>
              {candidate.blood_group && (
                <>
                  <div style={{ color: '#fff', fontSize: 7, opacity: 0.8 }}>Blood</div>
                  <div style={{ color: '#fff', fontSize: 11, fontWeight: 800 }}>{candidate.blood_group}</div>
                </>
              )}
            </div>
          </div>

          {/* Bottom tricolor stripe */}
          <div style={{
            height: 3,
            background: 'linear-gradient(to right, #FF6B00 33.33%, #ffffff 33.33%, #ffffff 66.66%, #138808 66.66%)',
          }} />
        </div>
      </div>

      {/* ── Status message ───────────────────────────────────── */}
      {status === 'loading' && (
        <div style={{ textAlign: 'center', color: '#FF6B00', fontSize: 13, fontWeight: 600, marginBottom: 10 }}>
          ⏳ {statusMsg}
        </div>
      )}
      {status === 'done' && (
        <div style={{ textAlign: 'center', color: '#138808', fontSize: 13, fontWeight: 600, marginBottom: 10 }}>
          ✅ {statusMsg}
        </div>
      )}
      {status === 'error' && (
        <div style={{ textAlign: 'center', color: '#dc2626', fontSize: 13, fontWeight: 600, marginBottom: 10 }}>
          ❌ {statusMsg}
        </div>
      )}

      {/* ── Download buttons ─────────────────────────────────── */}
      <div style={{ display: 'flex', gap: 10, justifyContent: 'center', flexWrap: 'wrap' }}>
        <button
          onClick={handleDownloadPDF}
          disabled={status === 'loading'}
          style={{
            padding: '11px 22px',
            background: status === 'loading' ? '#9ca3af' : '#000080',
            color: '#fff', border: 'none', borderRadius: 10,
            fontSize: 13, fontWeight: 700, cursor: status === 'loading' ? 'not-allowed' : 'pointer',
            fontFamily: 'inherit', display: 'flex', alignItems: 'center', gap: 6,
          }}
        >
          📄 Download PDF
        </button>
        <button
          onClick={handleDownloadImage}
          disabled={status === 'loading'}
          style={{
            padding: '11px 22px',
            background: status === 'loading' ? '#9ca3af' : '#138808',
            color: '#fff', border: 'none', borderRadius: 10,
            fontSize: 13, fontWeight: 700, cursor: status === 'loading' ? 'not-allowed' : 'pointer',
            fontFamily: 'inherit', display: 'flex', alignItems: 'center', gap: 6,
          }}
        >
          🖼️ Download Image
        </button>
      </div>
    </div>
  );
}

function InfoRow({ label, value }) {
  if (!value) return null;
  return (
    <div style={{ display: 'flex', gap: 4, fontSize: 10 }}>
      <span style={{ color: '#6b7280', fontWeight: 600, minWidth: 68, flexShrink: 0 }}>{label}:</span>
      <span style={{ color: '#1f2937', fontWeight: 500, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
        {value}
      </span>
    </div>
  );
}
